from pathlib import Path

path = Path('l5/final_qa_r1_08_24_repair.py')
text = path.read_text(encoding='utf-8')
old = '''sp³ 杂化可以理解为一个 s 轨道和三个 p 轨道重新组合，形成四个能量等价、空间方向不同的杂化轨道。四条 ψ₁ 到 ψ₄ 的公式都有共同的 1/2 系数，表示每个杂化轨道都由 ψs、ψpx、ψpy 和 ψpz 按相同权重组合而成。它们之间的区别不在于参与的轨道种类，而在于 px、py、pz 各项前面的正负号不同。正负号改变了波函数在空间中的相位组合，因此四个杂化轨道指向不同方向。由于四个组合在数学上对称，它们形成四个彼此等价的 sp³ 轨道。为了使轨道之间的排斥尽可能小，四个方向在空间中排成四面体结构，理想键角约为 109.5°。在真实晶体或分子中，外部应变、邻近原子的影响或分子结构差异会使键角偏离理想值，例如氨等体系的键角会略小。讲解这页时不需要逐字念每条公式，而要强调：s 与 p 的不同加减组合把原本的原子轨道转化为四个指向四面体顶点的成键方向。'''
new = '''sp³ 杂化可以理解为一个 s 轨道和三个 p 轨道重新组合，形成四个能量等价、空间方向不同的杂化轨道。四条 ψ₁ 到 ψ₄ 的公式都有共同的 1/2 系数，表示每个杂化轨道都由 ψs、ψpx、ψpy 和 ψpz 按相同权重组合而成。它们之间的区别不在于参与的轨道种类，而在于 px、py、pz 各项前面的正负号不同。正负号改变了波函数在空间中的相位组合，因此四个杂化轨道指向不同方向。由于四个组合在数学上对称，它们形成四个彼此等价的 sp³ 轨道。为了使轨道之间的排斥尽可能小，四个方向在空间中排成四面体结构，理想键角约为 109.5°。从能量和成键角度看，杂化不是增加电子数，而是把同一价层的基函数换成更适合成键方向的线性组合。每个 sp³ 轨道同时含有 s 特征和 p 特征，因此在与相邻原子轨道重叠时能够形成强而定向的共价键。在硅晶体中，四个近邻原子沿四面体方向排列，这与四个等价杂化轨道的空间取向相对应。在真实晶体或分子中，外部应变、邻近原子的影响或分子结构差异会使键角偏离理想值，例如氨等体系的键角会略小。讲解这页时不需要逐字念每条公式，而要强调：s 与 p 的不同加减组合把原本的原子轨道转化为四个指向四面体顶点的成键方向。'''
if old not in text:
    raise SystemExit('Target page 20 notes paragraph not found')
path.write_text(text.replace(old, new), encoding='utf-8')
print('Patched page 20 notes paragraph for Final QA R1')
